/**
 * webhook-replay BullMQ worker — dead-letter queue processor.
 *
 * Triggered when:
 *   1. Admin manually re-enqueues a failed event from POST /api/admin/webhooks/replay
 *   2. Reconciliation cron (S15+) detects drift and auto-enqueues
 *
 * Strategy: load the webhook_events row by (source, event_id), parse the stored
 * payload JSONB, then call the same process*Event helper used by the live route —
 * bypassing signature verification. This is safe because only service-role-authorized
 * internal callers (admin endpoint + future cron) can enqueue replay jobs.
 *
 * BullMQ config:
 *   attempts: 3
 *   backoff: { type: 'exponential', delay: 30_000 }  → ~30s, ~5min, ~1h
 *   After 3 failures: mark webhook_events.error = 'DEAD_LETTER'
 *
 * The job queue name is 'inkos-jobs' (shared queue, filtered by job.name).
 *
 * INVARIANT 7: Dodo (L1) and Stripe (L2) abstractions never share a module.
 * This worker imports process-stripe-event and process-dodo-event through
 * relative paths (workers cannot use @/ aliases).
 */

import { Worker } from 'bullmq'
import { supabase } from '../lib/supabase.js'
import { logger } from '../lib/logger.js'
import { workerEnv } from '../lib/env.js'

// ---------------------------------------------------------------------------
// Relative imports to the extracted processors
// Workers NEVER import from next/* — use relative paths to lib/payments/*.
// These modules import from @/lib/* which is only valid in the Next.js app
// context. For workers we need plain relative resolution without the alias.
// SOLUTION: we dynamically resolve the actual process*Event functions at
// runtime by importing the compiled JS. Since ts-node / tsx resolves
// path aliases via tsconfig.json in the workers/ dir, we import via relative
// path from the project root.
//
// NOTE: workers/tsconfig.json must extend the root tsconfig and include
// "paths": { "@/*": ["../"] } or the workers use relative paths.
// Existing workers use ../lib/* (relative). We follow the same pattern here
// but the process-dodo-event and process-stripe-event helpers import from
// @/lib/... which is the Next.js app context. They cannot run directly in
// the worker process.
//
// CORRECT APPROACH per plan §5.3 simpler path: the replay worker calls the
// Supabase DB directly using the same logic — without importing the Next.js
// helpers. We inline the minimal dispatch needed: load row, call processEvent
// via direct DB RPC, update row. The heavy lifting (RPC calls) is the same
// code path; we avoid importing Next.js server modules.
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// Stripe replay dispatcher
// Calls the same RPCs as process-stripe-event.ts without Next.js imports.
// ---------------------------------------------------------------------------

async function replayStripeEvent(
  rawPayload: unknown,
  eventType: string,
  jobLog: ReturnType<typeof logger.child>,
): Promise<void> {
  jobLog.info({ eventType }, 'webhook-replay: replaying stripe event')

  // The payload stored in webhook_events is the full Stripe.Event object.
  // We dispatch to the appropriate RPC based on event type.
  // Only the event types handled in process-stripe-event.ts need cases here.
  const rpc = supabase.rpc.bind(supabase) as unknown as UntypedRpcFn

  // We re-use the stored payload object — Stripe.Event shape
  const event = rawPayload as Record<string, unknown>
  const dataObj = (event['data'] as Record<string, unknown>)?.['object'] as Record<string, unknown> ?? {}

  switch (eventType) {
    case 'account.updated': {
      const account = dataObj
      const onboardingStatus = deriveStripeOnboardingStatus(account)
      const capabilities = (account['capabilities'] as Record<string, string>) ?? {}
      const requirements = account['requirements'] as Record<string, unknown> | undefined
      const currentDeadline = requirements?.['current_deadline']
      const requirementsDueBy = typeof currentDeadline === 'number'
        ? new Date(currentDeadline * 1_000).toISOString()
        : null

      const { error } = await rpc('stripe_connected_account_update_from_webhook', {
        p_account_id: account['id'],
        p_onboarding_status: onboardingStatus,
        p_capabilities: {
          charges_enabled: account['charges_enabled'] === true,
          payouts_enabled: account['payouts_enabled'] === true,
          transfers: capabilities['transfers'] === 'active',
          tax_reporting_us_1099_nec: capabilities['tax_reporting_us_1099_nec'] === 'active',
        },
        p_country: account['country'] ?? 'US',
        p_default_currency: account['default_currency'] ?? 'usd',
        p_restricted_reason: requirements?.['disabled_reason'] ?? null,
        p_requirements_due_by: requirementsDueBy,
      })
      if (error) throw new Error(`account.updated RPC failed: ${error.message}`)
      break
    }

    case 'payment_intent.succeeded':
    case 'payment_intent.payment_failed':
    case 'payment_intent.canceled': {
      const pi = dataObj
      const latestCharge = pi['latest_charge']
      const chargeId =
        typeof latestCharge === 'string'
          ? latestCharge
          : (latestCharge as Record<string, string> | null)?.['id'] ?? null

      const statusMap: Record<string, string> = {
        'payment_intent.succeeded': 'succeeded',
        'payment_intent.payment_failed': 'requires_payment_method',
        'payment_intent.canceled': 'canceled',
      }

      const { error } = await rpc('stripe_charge_update_status_from_webhook', {
        p_payment_intent_id: pi['id'],
        p_status: statusMap[eventType],
        p_charge_id: chargeId,
        p_transfer_id: null,
        p_application_fee_id: null,
      })
      if (error) throw new Error(`${eventType} RPC failed: ${error.message}`)
      break
    }

    case 'charge.dispute.created': {
      const dispute = dataObj
      const chargeField = dispute['charge']
      const chargeId =
        typeof chargeField === 'string'
          ? chargeField
          : (chargeField as Record<string, string> | null)?.['id'] ?? null

      if (!chargeId) {
        jobLog.warn('webhook-replay: dispute missing charge id — skipping')
        return
      }

      // Resolve studio_id from stripe_charges
      const { data: chargeRow } = await supabase
        .from('stripe_charges' as 'projects')
        .select('studio_id' as never)
        .eq('charge_id' as never, chargeId)
        .maybeSingle()

      const studioId = (chargeRow as Record<string, string> | null)?.['studio_id'] ?? null
      if (!studioId) {
        jobLog.warn({ chargeId }, 'webhook-replay: could not resolve studio_id for dispute')
        return
      }

      const evidenceDetails = dispute['evidence_details'] as Record<string, number> | undefined
      const evidenceDueBy = evidenceDetails?.['due_by']
        ? new Date(evidenceDetails['due_by'] * 1_000).toISOString()
        : new Date(Date.now() + 7 * 24 * 60 * 60 * 1_000).toISOString()

      const amount = typeof dispute['amount'] === 'number' ? dispute['amount'] : 0
      const { error } = await rpc('stripe_dispute_record', {
        p_studio_id: studioId,
        p_dispute_id: dispute['id'],
        p_charge_id: chargeId,
        p_reason: dispute['reason'],
        p_status: dispute['status'],
        p_amount_cents: amount,
        p_currency: dispute['currency'] ?? 'usd',
        p_evidence_due_by: evidenceDueBy,
      })
      if (error) throw new Error(`dispute.created RPC failed: ${error.message}`)
      break
    }

    case 'charge.dispute.closed': {
      const dispute = dataObj
      const amount = typeof dispute['amount'] === 'number' ? dispute['amount'] : 0
      const resolvedAmountCents = dispute['status'] === 'lost' ? amount : null

      const { error } = await rpc('stripe_dispute_update_status_from_webhook', {
        p_dispute_id: dispute['id'],
        p_status: dispute['status'],
        p_resolved_at: new Date().toISOString(),
        p_resolved_amount_cents: resolvedAmountCents,
      })
      if (error) throw new Error(`dispute.closed RPC failed: ${error.message}`)
      break
    }

    default:
      jobLog.info({ eventType }, 'webhook-replay: stripe event type has no replay handler — marking done')
  }
}

function deriveStripeOnboardingStatus(
  account: Record<string, unknown>,
): 'active' | 'restricted' | 'pending' | 'rejected' {
  if (account['charges_enabled'] === true && account['payouts_enabled'] === true) return 'active'
  const requirements = account['requirements'] as Record<string, unknown> | undefined
  if (requirements?.['disabled_reason']) return 'restricted'
  const errors = requirements?.['errors']
  if (Array.isArray(errors) && errors.length > 0) return 'restricted'
  return 'pending'
}

