input.new_string:
/**
 * Minimal Supabase client interface — only the operations this module uses.
 * Structural (not nominal) so both @supabase/ssr and @supabase/supabase-js clients satisfy it.
 *
 * `rpc` and `from` are typed as `(...args: never[]) => unknown` with a `bind` method.
 * This matches the Function prototype shape the callers use: `supabase.rpc.bind(supabase)`.
 * The `as unknown as UntypedRpc` cast that follows handles the parameter type discrepancy.
 */
export interface SupabaseServiceClient {
  rpc: { bind(thisArg: unknown): (...args: never[]) => unknown }
  from: { bind(thisArg: unknown): (...args: never[]) => unknown }
}

